import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.C8R-a4p3.js";import"./chunks/assets.B6YiSQcu.js";var i=JSON.parse(`{"title":"The Agentic Method","description":"How Reza Bazdar ships production software with OpenCode, Codex, Claude Code and the Hermes agent — brief, generate, review, deploy.","frontmatter":{"title":"The Agentic Method","description":"How Reza Bazdar ships production software with OpenCode, Codex, Claude Code and the Hermes agent — brief, generate, review, deploy."},"headers":[],"relativePath":"en/about/how-i-work/index.md","filePath":"en/about/how-i-work/index.md"}`),a={name:`en/about/how-i-work/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="the-agentic-method" tabindex="-1">The Agentic Method <a class="header-anchor" href="#the-agentic-method" aria-label="Permalink to “The Agentic Method”">​</a></h1><p>I practice <strong>agentic coding</strong> as a daily discipline, not a demo trick. My daily drivers are <strong>OpenCode</strong>, <strong>OpenAI Codex</strong> and <strong>Claude Code</strong>, orchestrated by <strong>Hermes Agent</strong> — my own self-hosted agent infrastructure. Together they behave like a small engineering team that never sleeps, and I am its tech lead.</p><p>This is not &quot;AI writes everything while I watch&quot;. Delegating to agents is a skill with the same seriousness as writing code by hand: you learn to write specs instead of functions, to design review checkpoints instead of debug sessions, and to audit diffs the way a senior engineer reviews a junior — respectfully, but relentlessly.</p><h2 id="the-loop-that-ships-features" tabindex="-1">The loop that ships features <a class="header-anchor" href="#the-loop-that-ships-features" aria-label="Permalink to “The loop that ships features”">​</a></h2><ol><li><strong>Brief the agents.</strong> I turn an idea into a precise, testable specification: scope, edge cases, acceptance criteria. A good brief is 80% of the result.</li><li><strong>Generate and iterate.</strong> Agents implement in parallel — one refactors, another writes tests, a third prepares deployment. I steer, unblock and re-scope in real time.</li><li><strong>Human review.</strong> I audit every diff myself: security, architecture, edge cases, performance. Agent output is a proposal, never a promise.</li><li><strong>Deploy and monitor.</strong> Ship to the edge, watch logs and metrics, and feed every lesson back into the next brief.</li></ol><figure class="concept-illustration"><img src="/Usf/assets/img/agentic-loop.svg" alt="The four-step agentic loop: brief, generate, review, deploy" loading="lazy"><figcaption>The loop I run every day — with humans exactly where judgment matters.</figcaption></figure><h2 id="why-this-is-a-real-engineering-skill" tabindex="-1">Why this is a real engineering skill <a class="header-anchor" href="#why-this-is-a-real-engineering-skill" aria-label="Permalink to “Why this is a real engineering skill”">​</a></h2><p>Directing agents exposes weaknesses that typing speed never will. If your architecture is vague, agents amplify the vagueness. If your tests are weak, agents pass them confidently. If your spec is ambiguous, you get ten creative interpretations you did not ask for. Working this way forces me to think more clearly than traditional development ever did — the agents are mirrors, and they are unforgiving.</p><blockquote><p>The skill of the next decade is not typing faster — it is directing intelligent agents with the precision of a senior engineer and the taste of a product designer.</p></blockquote><p>Every project on this site — from the <a href="/Usf/en/projects/netpilot/">NetPilot</a> network toolkit to this very portfolio — was designed, reviewed and shipped through that loop. The <a href="/Usf/en/agentic/overview/">Agentic Coding</a> section breaks down each tool I use.</p>`,10)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};